/* SPECTRA20 — ChatGPT作。極彩色のフラクタル現象20種。タッチは「点」ではなく法則を変える。 */
window.Spectra20=function(canvas,index){
const ctx=canvas.getContext('2d',{alpha:false});let W=0,H=0,D=1,live=0,seed=Math.random()*999999,marks=[],drag=false;
const N=['BRANCH','CHAOS','JULIA','MANDELBROT','KOCH','DRAGON','SIERPINSKI','CIRCLES','APOLLONIAN','HILBERT','CARPET','NEWTON','BURN','ORBIT','CORAL','LACE','FLAME','MIRROR','GROW','VOID'];
const PAL=[['#ff3b30','#ffd60a','#32d74b','#64d2ff','#bf5af2'],['#00f5ff','#ff2bd6','#ffe600','#62ff5f','#ff6b35'],['#ff1744','#7c4dff','#00e5ff','#76ff03','#ffea00'],['#ff00a8','#00fff0','#fffb00','#6a00ff','#ff5e00'],['#ff4d00','#ffcc00','#00e676','#00b0ff','#d500f9'],['#00e5ff','#2979ff','#d500f9','#ff4081','#ffea00'],['#ff0055','#00ff99','#00ccff','#ffff00','#aa00ff'],['#ff006e','#fbff12','#00f5d4','#00bbf9','#9b5de5'],['#ff3d00','#ffea00','#00c853','#00b8d4','#6200ea'],['#ff0080','#00ffff','#7cff00','#ffea00','#6c00ff'],['#f50057','#00e5ff','#76ff03','#ff9100','#651fff'],['#ff1744','#00e676','#00b0ff','#d500f9','#ffea00'],['#ff00ff','#00ffff','#ffff00','#ff3300','#33ff66'],['#ff6d00','#ffea00','#00e676','#00b0ff','#d500f9'],['#ff004c','#ff8a00','#ffe600','#00ff9d','#00b8ff'],['#7c00ff','#ff00aa','#00f0ff','#aaff00','#fff000'],['#ff0040','#ff7a00','#ffe600','#00ff66','#00ddff'],['#00ffcc','#00aaff','#8a2be2','#ff00aa','#ffea00'],['#ff006e','#00ffea','#8cff00','#ffb000','#7a00ff'],['#ff0055','#00ffff','#fff000','#ff7b00','#8b00ff']];
function resize(){D=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*D;canvas.height=H*D;ctx.setTransform(D,0,0,D,0,0)}addEventListener('resize',resize);resize();
function hash(n){let x=Math.sin(n*127.1+seed*311.7)*43758.5453123;return x-Math.floor(x)}
function col(k,t=0){const p=PAL[index%PAL.length];return p[Math.abs(Math.floor(k+t))%p.length]}
function bg(){ctx.fillStyle='#020207';ctx.fillRect(0,0,W,H)}
function pt(x,y,r,c,a=.8){ctx.globalAlpha=a;ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill()}
function seg(x1,y1,x2,y2,c,a=.7,w=1){ctx.globalAlpha=a;ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()}
function law(x,y){let q=0,S=Math.min(W,H);for(const m of marks){const d=Math.hypot(x-m.x,y-m.y)+1;q+=Math.exp(-d*d/(S*S*.025))*((m.x/W)-.5)*2}return q}
function branch(x,y,len,a,d,k){if(d<0||len<1.2)return;const aa=a+Math.sin(k*1.7+d)*.08+law(x,y)*.35;const x2=x+Math.cos(aa)*len,y2=y+Math.sin(aa)*len;seg(x,y,x2,y2,col(k,live*1.3),.72,.7+d*.16);const sp=.42+law(x2,y2)*.16;branch(x2,y2,len*.72,aa-sp,d-1,k+1.1);branch(x2,y2,len*.72,aa+sp,d-1,k+2.2)}
function chaos(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2,v=[[cx,cy-S*.43],[cx-S*.43,cy+S*.34],[cx+S*.43,cy+S*.34]];let x=cx,y=cy;for(let i=0;i<18000;i++){const p=v[Math.floor(hash(i)*3)],f=.5+Math.sin(law(x,y)*4)*.055;x+=(p[0]-x)*f;y+=(p[1]-y)*f;if(i>40&&i%2===0)pt(x,y,.65,col(i*.012,live*1.8),.75)}}
function escape(mandel){bg();const S=Math.min(W,H),step=3.4/S,ox=W/2,oy=H/2,max=70,m=marks[0]||{x:W*.7,y:H*.45},ccx=-.72+(m.x/W-.5)*.75,ccy=.18+(m.y/H-.5)*.65;for(let py=0;py<H;py+=2)for(let px=0;px<W;px+=2){let x=(px-ox)*step,y=(py-oy)*step,zx=mandel?0:x,zy=mandel?0:y,cx=mandel?x:ccx,cy=mandel?y:ccy,n=0;for(;n<max;n++){const xx=zx*zx-zy*zy+cx,yy=2*zx*zy+cy;zx=xx;zy=yy;if(zx*zx+zy*zy>16)break}if(n<max){const sm=n+1-Math.log(Math.log(Math.hypot(zx,zy)))/Math.log(2);ctx.fillStyle=col(sm*.18,live*2);ctx.globalAlpha=.92;ctx.fillRect(px,py,2,2)}}}
function koch(a,b,c,d,depth,k){if(depth===0){seg(a,b,c,d,col(k*.35,live),.86,1);return}const dx=(c-a)/3,dy=(d-b)/3,ax=a+dx,ay=b+dy,bx=a+dx*2,by=b+dy*2,ca=Math.cos(Math.PI/3),sa=Math.sin(Math.PI/3),px=ax+dx*ca-dy*sa,py=ay+dx*sa+dy*ca;koch(a,b,ax,ay,depth-1,k);koch(ax,ay,px,py,depth-1,k+1);koch(px,py,bx,by,depth-1,k+2);koch(bx,by,c,d,depth-1,k+3)}
function dragon(){bg();const S=Math.min(W,H),depth=12;let turns=[1];for(let r=0;r<depth;r++){const n=turns.slice();n.push(1);for(let j=turns.length-1;j>=0;j--)n.push(-turns[j]);turns=n}let a=-.22+((marks[0]?.x??W/2)-W/2)/S*.8,len=S*.68/Math.pow(2,depth/2),x=W/2-S*.34,y=H/2+S*.1;for(let i=0;i<turns.length;i++){const nx=x+Math.cos(a)*len,ny=y+Math.sin(a)*len;seg(x,y,nx,ny,col(i*.018,live*2),.72,.8);x=nx;y=ny;a+=turns[i]*Math.PI/2*(1+.05*Math.sin(live))}}
function sier(){bg();const S=Math.min(W,H)*.88,cx=W/2,cy=H/2;function go(a,b,c,d,k){if(d===0){pt(a[0],a[1],1.05,col(k,live*2),.8);return}const ab=[(a[0]+b[0])/2,(a[1]+b[1])/2],bc=[(b[0]+c[0])/2,(b[1]+c[1])/2],ca=[(c[0]+a[0])/2,(c[1]+a[1])/2];go(a,ab,ca,d-1,k);go(ab,b,bc,d-1,k+1.2);go(ca,bc,c,d-1,k+2.4)}go([cx,cy-S*.5],[cx-S*.5,cy+S*.35],[cx+S*.5,cy+S*.35],7,0)}
function circles(){bg();const S=Math.min(W,H);function r(x,y,s,d,k){if(d<0||s<1.5)return;ctx.globalAlpha=.6;ctx.strokeStyle=col(k,live);ctx.lineWidth=Math.max(.5,d*.2);ctx.beginPath();ctx.arc(x,y,s,0,7);ctx.stroke();const q=.46+law(x,y)*.07;r(x-s*q,y,s*q,d-1,k+1);r(x+s*q,y,s*q,d-1,k+2);r(x,y-s*q,s*q,d-1,k+3);r(x,y+s*q,s*q,d-1,k+4)}r(W/2,H/2,S*.31,6,0)}
function apollo(){bg();const S=Math.min(W,H);function r(x,y,s,d,k){if(d<0||s<2)return;ctx.globalAlpha=.72;ctx.strokeStyle=col(k,live);ctx.lineWidth=.7;ctx.beginPath();ctx.arc(x,y,s,0,7);ctx.stroke();const q=s*.43,a0=law(x,y)+live*.1;for(let j=0;j<3;j++){const a=a0+j*Math.PI*2/3;r(x+Math.cos(a)*(s-q),y+Math.sin(a)*(s-q),q,d-1,k+j+1)}}r(W/2,H/2,S*.36,5,0)}
function hilbert(){bg();const S=Math.min(W,H)*.82,depth=6,pts=[];function h(x0,y0,xi,xj,yi,yj,n){if(n<=0){pts.push([x0+(xi+yi)/2,y0+(xj+yj)/2]);return}h(x0,y0,yi/2,yj/2,xi/2,xj/2,n-1);h(x0+xi/2,y0+xj/2,xi/2,xj/2,yi/2,yj/2,n-1);h(x0+xi/2+yi/2,y0+xj/2+yj/2,xi/2,xj/2,yi/2,yj/2,n-1);h(x0+xi/2+yi,y0+xj/2+yj,-yi/2,-yj/2,-xi/2,-xj/2,n-1)}h(W/2-S/2,H/2-S/2,S,0,0,S,depth);for(let i=1;i<pts.length;i++){const a=pts[i-1],b=pts[i];seg(a[0],a[1],b[0],b[1],col(i*.02,live*2),.74,1.15)}}
function carpet(){bg();const S=Math.min(W,H)*.82;function sq(x,y,s,d,k){if(d===0){ctx.fillStyle=col(k,live);ctx.globalAlpha=.82;ctx.fillRect(x-s/2,y-s/2,s,s);return}const g=s/3;for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++)if(xx||yy)sq(x+xx*g,y+yy*g,g,d-1,k+xx+yy+3)}sq(W/2,H/2,S,5,0)}
function newton(){bg();const S=Math.min(W,H)*.43;for(let py=0;py<H;py+=3)for(let px=0;px<W;px+=3){let x=(px-W/2)/S,y=(py-H/2)/S,n=0;for(;n<18;n++){const r=x*x+y*y;if(r<1e-8)break;const f=x*x*x-3*x*y*y-1,g=3*x*x*y-y*y*y,A=3*x*x-3*y*y,B=6*x*y,den=A*A+B*B;if(den<1e-9)break;const nx=x-(f*A+g*B)/den,ny=y-(g*A-f*B)/den;x=nx;y=ny}ctx.fillStyle=col(Math.floor((Math.atan2(y,x)+Math.PI)*2.4),live*2);ctx.globalAlpha=.86;ctx.fillRect(px,py,3,3)}}
function burn(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let i=0;i<6500;i++){let a=hash(i)*Math.PI*2,r=Math.sqrt(hash(i+3))*S*.42,x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;for(let n=0;n<8;n++){const d=Math.hypot(x-cx,y-cy)/S;a+=Math.sin(r*.03+n+live)*(.5+d*2)+law(x,y);r*=.91;x=cx+Math.cos(a)*r;y=cy+Math.sin(a)*r;if(n>2)pt(x,y,.5,col(i*.003+n,live*2),.22)}}}
function orbit(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2,tx=marks[0]?.x??cx,ty=marks[0]?.y??cy;for(let j=0;j<18;j++){let px=tx,py=ty;for(let i=0;i<240;i++){const u=i/239,r=S*.012+j*S*.017+u*S*.3,a=u*Math.PI*(2.1+j*.12)+live*(.25+j*.01)+law(px,py);const x=tx+Math.cos(a)*r,y=ty+Math.sin(a)*r*.62;seg(px,py,x,y,col(j+i*.012,live),.3,.55);if(i%5===0)pt(x,y,1.15,col(j+i*.012,live),.65);px=x;py=y}}}
function coral(){bg();const S=Math.min(W,H);function g(x,y,a,len,d,k){if(d<0||len<1)return;const aa=a+law(x,y)*.65,x2=x+Math.cos(aa)*len,y2=y+Math.sin(aa)*len;seg(x,y,x2,y2,col(k,live),.62,Math.max(.45,d*.17));g(x2,y2,aa-.4,len*.69,d-1,k+1);g(x2,y2,aa+.4,len*.69,d-1,k+2);if(d%2===0)g(x2,y2,aa+.2,len*.5,d-2,k+3)}g(W/2,H*.94,-Math.PI/2,S*.18,8,0);g(W*.16,H*.9,-1.15,S*.12,7,2);g(W*.84,H*.9,-1.99,S*.12,7,4)}
function lace(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;for(let r=0;r<12;r++){const R=S*.04+r*S*.035;let px=0,py=0;for(let i=0;i<=240;i++){const a=i/240*Math.PI*2,rr=R*(1+.22*Math.sin(a*(3+r%4)+live*1.4)+.08*Math.sin(a*9-r)),x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;if(i)seg(px,py,x,y,col(r,live),.5,r%3===0?1.05:.55);px=x;py=y}}}
function flame(){bg();const S=Math.min(W,H),cx=W/2,cy=H*.88;for(let i=0;i<100;i++){let a=-Math.PI/2+(hash(i)-.5)*1.6,len=S*(.08+hash(i+1)*.22),x=cx+(hash(i+2)-.5)*S*.3,y=cy;for(let d=0;d<8;d++){a+=(hash(i*9+d)-.5)*.8*.18+law(x,y)*.18;const nx=x+Math.cos(a)*len,ny=y+Math.sin(a)*len;seg(x,y,nx,ny,col(i*.08+d,live*2),.55,1.05);x=nx;y=ny;len*=.72}}}
function mirror(){bg();const S=Math.min(W,H),cx=W/2,cy=H/2;function r(x,y,s,d,k,a){if(d<0)return;ctx.globalAlpha=.6;ctx.strokeStyle=col(k,live);ctx.lineWidth=1;ctx.strokeRect(x-s,y-s,s*2,s*2);const q=.46+law(x,y)*.08,pts=[[-1,-1],[1,-1],[-1,1],[1,1]];for(const p of pts){const dx=p[0]*s*q,dy=p[1]*s*q,ca=Math.cos(a),sa=Math.sin(a);r(cx+(x+dx-cx)*ca-(y+dy-cy)*sa,cy+(x+dx-cx)*sa+(y+dy-cy)*ca,s*q,d-1,k+1,a+.08)}}r(cx,cy,S*.27,5,0,live*.15)}
function grow(){bg();const S=Math.min(W,H);function r(x,y,len,a,d,k){if(d<0||len<1)return;const tx=marks[0]?.x??W/2,ty=marks[0]?.y??H/2,dd=Math.hypot(x-tx,y-ty),f=Math.exp(-dd*dd/(S*S*.08));const aa=a+f*.9+Math.sin(live+d)*.02,x2=x+Math.cos(aa)*len,y2=y+Math.sin(aa)*len;seg(x,y,x2,y2,col(k+d,live),.72,.7+d*.1);r(x2,y2,len*.73,aa-.48,d-1,k+1);r(x2,y2,len*.73,aa+.48,d-1,k+2)}r(W/2,H/2,S*.24,-Math.PI/2,9,0)}
function voids(){bg();const S=Math.min(W,H);function q(x,y,s,d,k){if(d<0||s<2)return;ctx.globalAlpha=.8;ctx.strokeStyle=col(k,live);ctx.lineWidth=Math.max(.5,d*.16);ctx.strokeRect(x-s/2,y-s/2,s,s);if(d===0)return;const g=s/3;for(let yy=-1;yy<=1;yy++)for(let xx=-1;xx<=1;xx++)if(Math.abs(xx)+Math.abs(yy)>0)q(x+xx*g,y+yy*g,g,d-1,k+xx+yy+4)}q(W/2,H/2,S*.82,5,0)}
function render(ph){live=ph;switch(index){case 0:bg();branch(W/2,H*.92,Math.min(W,H)*.28,-Math.PI/2,9,0);break;case 1:chaos();break;case 2:escape(false);break;case 3:escape(true);break;case 4:bg();{const S=Math.min(W,H)*.72,cx=W/2,cy=H/2;for(let j=0;j<3;j++){const a=j*Math.PI*2/3+live*.12;koch(cx+Math.cos(a)*S*.42,cy+Math.sin(a)*S*.42,cx+Math.cos(a+Math.PI*2/3)*S*.42,cy+Math.sin(a+Math.PI*2/3)*S*.42,4,j*5)}}break;case 5:dragon();break;case 6:sier();break;case 7:circles();break;case 8:apollo();break;case 9:hilbert();break;case 10:carpet();break;case 11:newton();break;case 12:burn();break;case 13:orbit();break;case 14:coral();break;case 15:lace();break;case 16:flame();break;case 17:mirror();break;case 18:grow();break;case 19:voids();break}ctx.globalAlpha=1}
function mutate(){seed=Math.random()*999999;marks=[];for(let i=0;i<1+(Math.random()*2|0);i++)marks.push({x:W*(.18+Math.random()*.64),y:H*(.2+Math.random()*.6)});render(live)}
function reset(){marks=[];seed=Math.random()*999999;render(live)}
function add(x,y){if(window.APKit&&APKit.isUI(x,y))return true;marks.push({x,y});if(marks.length>3)marks.shift();return true}
canvas.addEventListener('pointerdown',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;drag=true;add(e.clientX,e.clientY)});
canvas.addEventListener('pointermove',e=>{if(window.APKit&&APKit.isUI(e.clientX,e.clientY))return true;if(drag&&marks.length)marks[marks.length-1]={x:e.clientX,y:e.clientY}});
canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('pointercancel',()=>drag=false);
APKit.init({canvas,gifName:'spectra-'+String(index+1).padStart(2,'0')+'-'+N[index].toLowerCase()+'-loop',clockFormat:'spec',loopFrame:function(phase){render(phase)},buttons:[{label:'✦',name:'mutate',onClick:mutate},{label:'↻',name:'reset',onClick:reset}]});render(0);function tick(){live=(live+.008)%6.283185307;render(live);requestAnimationFrame(tick)}tick();
};